    // -- GPU particle attractors (pat-nzgdu.144) ---------------------------
    //
    // An attractor applies a per-particle force each frame to particles inside
    // its volume: `strength` scales it (negative repels), `attenuation` shapes
    // the falloff across the volume, `directionality` biases between a radial
    // pull toward the centre and a uniform push along the attractor's -Z, and
    // `cull_mask` selects which emitters it touches. Schemas are diffed against
    // `extension_api.json`.
    //
    // The base is abstract — Godot only instantiates the three shapes, which is
    // what makes the shape property (`size`/`radius`) the volume test.
    register_class(
        ClassRegistration::new("GPUParticlesAttractor3D")
            .parent("VisualInstance3D")
            .abstract_class()
            .property(
                PropertyInfo::new("strength", Variant::Float(1.0))
                    .with_accessors("get_strength", "set_strength"),
            )
            .property(
                PropertyInfo::new("attenuation", Variant::Float(1.0))
                    .with_accessors("get_attenuation", "set_attenuation"),
            )
            .property(
                PropertyInfo::new("directionality", Variant::Float(0.0))
                    .with_accessors("get_directionality", "set_directionality"),
            )
            // A 20-bit render layer mask; every layer on by default.
            .property(
                PropertyInfo::new("cull_mask", Variant::Int(0xFFFFF))
                    .with_accessors("get_cull_mask", "set_cull_mask"),
            ),
    );
    register_class(
        ClassRegistration::new("GPUParticlesAttractorBox3D")
            .parent("GPUParticlesAttractor3D")
            .property(
                PropertyInfo::new(
                    "size",
                    Variant::Vector3(gdcore::math::Vector3::new(2.0, 2.0, 2.0)),
                )
                .with_accessors("get_size", "set_size"),
            ),
    );
    register_class(
        ClassRegistration::new("GPUParticlesAttractorSphere3D")
            .parent("GPUParticlesAttractor3D")
            .property(
                PropertyInfo::new("radius", Variant::Float(1.0))
                    .with_accessors("get_radius", "set_radius"),
            ),
    );
    register_class(
        ClassRegistration::new("GPUParticlesAttractorVectorField3D")
            .parent("GPUParticlesAttractor3D")
            .property(
                PropertyInfo::new(
                    "size",
                    Variant::Vector3(gdcore::math::Vector3::new(2.0, 2.0, 2.0)),
                )
                .with_accessors("get_size", "set_size"),
            )
            // A Texture3D sampled for the force direction; Nil until assigned.
            .property(
                PropertyInfo::new("texture", Variant::Nil)
                    .with_accessors("get_texture", "set_texture"),
            ),
    );
    // -- GPUParticlesCollision* family (pat-0q2kx.231) -----------------------
    //
    // The collision half of the particle-volume family. Its attractor siblings
    // above were registered; these five were not, so a `.tscn` carrying a
    // collider failed class resolution outright.
    //
    // ⚠️ Several defaults are emphatically NOT the zero value, and each one is
    // the doc XML's:
    //   * `cull_mask` is 4294967295 (all 32 layers), not 0 — zero would make
    //     every collider ignore every particle.
    //   * `heightfield_mask` is 1048575 (2^20 - 1), a DIFFERENT width from
    //     cull_mask; copying cull_mask's value here would be wrong.
    //   * `resolution` is 2, not 0 — an enum whose default is not its first
    //     member.
    //   * `size` is Vector3(2, 2, 2), not ZERO — a zero box collides with
    //     nothing.
    register_class(
        // GDREGISTER_ABSTRACT_CLASS — the only abstract member of the family.
        ClassRegistration::new("GPUParticlesCollision3D")
            .parent("VisualInstance3D")
            .abstract_class()
            .property(
                PropertyInfo::new("cull_mask", Variant::Int(4294967295))
                    .with_accessors("get_cull_mask", "set_cull_mask"),
            ),
    );
    register_class(
        ClassRegistration::new("GPUParticlesCollisionBox3D")
            .parent("GPUParticlesCollision3D")
            .property(
                PropertyInfo::new(
                    "size",
                    Variant::Vector3(gdcore::math::Vector3::new(2.0, 2.0, 2.0)),
                )
                .with_accessors("get_size", "set_size"),
            ),
    );
