    // Godot's GUI intermediates. Patina parented the leaves straight onto
    // Control/Container and never registered these, so `is_class("BaseButton")`
    // was false for a Button — which is exactly why `control.rs` carries a
    // hardcoded BUTTON_CLASSES fallback list (pat-0q2kx.62).
    //
    // ⚠️ These MUST be registered in the same entry point as the leaves below.
    // `inheritance_chain` resolves parents by name at query time and stops at
    // the first unregistered name, so re-parenting without the base present
    // would sever Button from Control and Object entirely — worse than the gap
    // being fixed, and invisible to `cargo check`.
    if !class_exists("BaseButton") {
        register_class(
            ClassRegistration::new("BaseButton")
                .parent("Control")
                .abstract_class()
                .property(
                    PropertyInfo::new("disabled", Variant::Bool(false))
                        .with_accessors("is_disabled", "set_disabled"),
                )
                .property(
                    PropertyInfo::new("toggle_mode", Variant::Bool(false))
                        .with_accessors("is_toggle_mode", "set_toggle_mode"),
                )
                .property(
                    PropertyInfo::new("button_pressed", Variant::Bool(false))
                        .with_accessors("is_pressed", "set_pressed"),
                )
                .property(PropertyInfo::new("button_mask", Variant::Int(1)))
                .property(PropertyInfo::new("focus_mode", Variant::Int(2)))
                .property(PropertyInfo::new(
                    "keep_pressed_outside",
                    Variant::Bool(false),
                ))
                // The Shortcut resource itself; `shortcut_feedback` only
                // controls whether the press is animated (pat-s3rrv.175).
                .property(
                    PropertyInfo::new("shortcut", Variant::Nil)
                        .with_accessors("get_shortcut", "set_shortcut"),
                )
                .property(PropertyInfo::new("shortcut_feedback", Variant::Bool(true)))
                .property(PropertyInfo::new(
                    "shortcut_in_tooltip",
                    Variant::Bool(true),
                ))
                // ACTION_MODE_BUTTON_RELEASE = 1 is Godot's default: a click
                // fires on release, not on press.
                .property(
                    PropertyInfo::new("action_mode", Variant::Int(1))
                        .with_accessors("get_action_mode", "set_action_mode"),
                )
                .property(
                    PropertyInfo::new("button_group", Variant::Nil)
                        .with_accessors("get_button_group", "set_button_group"),
                )
                .signal(SignalInfo::new("pressed"))
                .signal(SignalInfo::new("button_down"))
                .signal(SignalInfo::new("button_up"))
                .signal(SignalInfo::new("toggled").arg("toggled_on")),
        );
    }
    if !class_exists("ButtonGroup") {
        // The resource that turns a set of toggle buttons into radio buttons
        // (pat-s3rrv.161). Registered beside `BaseButton`, whose `button_group`
        // property points at it.
        //
        // ⚠️ `get_pressed_button()`, `get_buttons()` and the `pressed(button)`
        // signal are documented on this class and are deliberately NOT declared
        // here. All three need the ButtonGroup itself as the receiver, and a
        // Patina resource is a VALUE with no object identity — `button_group`
        // reads as `Nil`, so no script can obtain the group to call or connect
        // to it. Declaring them would advertise a surface the engine cannot
        // dispatch. The behaviour they describe is implemented and tested at
        // `gdscene::control::{button_group_buttons, button_group_pressed_button}`;
        // only the resource-as-receiver is missing, and that is an engine-wide
        // gap rather than a button one.
        register_class(
            ClassRegistration::new("ButtonGroup")
                .parent("Resource")
                .property(
                    PropertyInfo::new("allow_unpress", Variant::Bool(false))
                        // ⚠️ `is_allow_unpress`, not `get_…` — a bool member
                        // whose getter does not follow the `get_` convention.
                        .with_accessors("is_allow_unpress", "set_allow_unpress"),
                )
                // ⚠️ Overrides Resource's own default of `false`. Godot makes a
                // ButtonGroup local to its scene so two instances of the same
                // scene do not share one radio group.
                .property(
                    PropertyInfo::new("resource_local_to_scene", Variant::Bool(true))
                        .with_accessors("is_local_to_scene", "set_local_to_scene"),
                ),
        );
    }
