    // pat-s3rrv.54: the filter family. `AudioEffectFilter : AudioEffect` carries
    // all four properties and the `FilterDB` slope enum; the seven concrete
    // leaves add NO members of their own (extension_api.json,
    // doc/classes/AudioEffectFilter.xml) — they exist purely so a bus layout
    // and the editor's Add-Effect list can name a response type. The biquad DSP
    // has been in `gdaudio::effects` all along; nothing could name it.
    if !class_exists("AudioEffectFilter") {
        register_class(
            ClassRegistration::new("AudioEffectFilter")
                .parent("AudioEffect")
                .property(
                    PropertyInfo::new("cutoff_hz", Variant::Float(2000.0))
                        .with_accessors("get_cutoff", "set_cutoff"),
                )
                .property(
                    PropertyInfo::new("resonance", Variant::Float(1.0))
                        .with_accessors("get_resonance", "set_resonance"),
                )
                .property(
                    PropertyInfo::new("gain", Variant::Float(1.0))
                        .with_accessors("get_gain", "set_gain"),
                )
                .property(
                    PropertyInfo::new("db", Variant::Int(0)).with_accessors("get_db", "set_db"),
                )
                // Slope in dB per octave; the value is an INDEX, not the dB
                // number, so DB_24 is 3 rather than 24.
                .enumeration(
                    EnumInfo::new("FilterDB")
                        .constant("DB_6", 0)
                        .constant("DB_12", 1)
                        .constant("DB_18", 2)
                        .constant("DB_24", 3),
                ),
        );
    }
