    // pat-s3rrv.53: the dynamics family. The DSP for all three already existed
    // in `gdaudio::effects` and was unit-tested, but nothing could NAME them —
    // ClassDB stopped at Distortion and the bus-layout constructor had no arm —
    // so a project whose Master bus ended in a compressor loaded with an empty
    // effect chain.
    //
    // Defaults are from `doc/classes/AudioEffect{Compressor,Limiter,HardLimiter}.xml`,
    // read from the vendored upstream rather than from the bead text, which
    // states HardLimiter's ceiling as -0.1; upstream says **-0.3**.
    if !class_exists("AudioEffectCompressor") {
        register_class(
            ClassRegistration::new("AudioEffectCompressor")
                .parent("AudioEffect")
                // ⚠️ `attack_us` is MICROSECONDS, and it is the only member of
                // this family in those units — the sibling is `release_ms`.
                // Feeding 20.0 to a millisecond attack is a 1000x error that
                // still "works", just with the wrong envelope.
                .property(
                    PropertyInfo::new("threshold", Variant::Float(0.0))
                        .with_accessors("get_threshold", "set_threshold"),
                )
                .property(
                    PropertyInfo::new("ratio", Variant::Float(4.0))
                        .with_accessors("get_ratio", "set_ratio"),
                )
                .property(
                    PropertyInfo::new("gain", Variant::Float(0.0))
                        .with_accessors("get_gain", "set_gain"),
                )
                .property(
                    PropertyInfo::new("attack_us", Variant::Float(20.0))
                        .with_accessors("get_attack_us", "set_attack_us"),
                )
                .property(
                    PropertyInfo::new("release_ms", Variant::Float(250.0))
                        .with_accessors("get_release_ms", "set_release_ms"),
                )
                .property(
                    PropertyInfo::new("mix", Variant::Float(1.0))
                        .with_accessors("get_mix", "set_mix"),
                )
                // StringName in Godot, defaulting to the empty name: the bus
                // this compressor ducks against.
                .property(
                    PropertyInfo::new("sidechain", Variant::String(String::new()))
                        .with_accessors("get_sidechain", "set_sidechain"),
                ),
        );
    }
