    // Theme resources (pat-nzgdu.89): Theme is a Resource; ThemeDB is the
    // Object singleton exposing the project + default themes to scripts.
    if !class_exists("Theme") {
        register_class(
            ClassRegistration::new("Theme")
                .parent("Resource")
                .property(PropertyInfo::new("default_base_scale", Variant::Float(0.0)))
                // A Font ref with no documented default, i.e. null.
                .property(PropertyInfo::new("default_font", Variant::Nil))
                .property(PropertyInfo::new("default_font_size", Variant::Int(-1))),
        );
    }
    // ⚠️ The five properties below were registered without their accessors and
    // without a single method, so `class_get_method_list("ThemeDB")` came back
    // EMPTY while `class_exists("ThemeDB")` answered true — which is exactly
    // why this read as done (pat-s3rrv.126).
    //
    // All twelve names are transcribed from `scene/theme/theme_db.cpp:415-427`,
    // not derived from the property names: Godot binds `get_default_theme` and
    // `get_project_theme` as plain methods and the other ten as the members'
    // accessors. None is bound const, so none is marked const here.
    if !class_exists("ThemeDB") {
        register_class(
            ClassRegistration::new("ThemeDB")
                .signal(SignalInfo::new("fallback_changed"))
                .parent("Object")
                .property(
                    PropertyInfo::new("fallback_base_scale", Variant::Float(1.0))
                        .with_accessors("get_fallback_base_scale", "set_fallback_base_scale"),
                )
                .property(
                    PropertyInfo::new("fallback_font_size", Variant::Int(16))
                        .with_accessors("get_fallback_font_size", "set_fallback_font_size"),
                )
                .property(
                    PropertyInfo::new("fallback_font", Variant::Nil)
                        .with_accessors("get_fallback_font", "set_fallback_font"),
                )
                .property(
                    PropertyInfo::new("fallback_icon", Variant::Nil)
                        .with_accessors("get_fallback_icon", "set_fallback_icon"),
                )
                .property(
                    PropertyInfo::new("fallback_stylebox", Variant::Nil)
                        .with_accessors("get_fallback_stylebox", "set_fallback_stylebox"),
                )
                // The two real methods. Both return a Theme, and Godot returns
                // null from `get_project_theme` when the project sets no
                // `gui/theme/custom` — hence a Nil marker carrying the class
                // name rather than a Theme-typed value.
                .method(MethodInfo::new("get_default_theme", 0).returns_of(Variant::Nil, "Theme"))
                .method(MethodInfo::new("get_project_theme", 0).returns_of(Variant::Nil, "Theme"))
                // The ten member accessors. Argument names come from the
                // `D_METHOD("set_fallback_*", "<arg>")` entries upstream.
                .method(
                    MethodInfo::new("set_fallback_base_scale", 1)
                        .with_arguments(vec![PropertyInfo::new("base_scale", Variant::Float(0.0))]),
                )
                .method(MethodInfo::new("get_fallback_base_scale", 0).returns(Variant::Float(0.0)))
                .method(MethodInfo::new("set_fallback_font", 1).with_arguments(vec![
                    PropertyInfo::new("font", Variant::Nil).with_hint_string("Font"),
                ]))
                .method(MethodInfo::new("get_fallback_font", 0).returns_of(Variant::Nil, "Font"))
                .method(
                    MethodInfo::new("set_fallback_font_size", 1)
                        .with_arguments(vec![PropertyInfo::new("font_size", Variant::Int(0))]),
                )
                .method(MethodInfo::new("get_fallback_font_size", 0).returns(Variant::Int(0)))
                .method(MethodInfo::new("set_fallback_icon", 1).with_arguments(vec![
                    PropertyInfo::new("icon", Variant::Nil).with_hint_string("Texture2D"),
                ]))
                .method(
                    MethodInfo::new("get_fallback_icon", 0).returns_of(Variant::Nil, "Texture2D"),
                )
                .method(
                    MethodInfo::new("set_fallback_stylebox", 1)
                        .with_arguments(vec![PropertyInfo::new("stylebox", Variant::Nil)
                            .with_hint_string("StyleBox")]),
                )
                .method(
                    MethodInfo::new("get_fallback_stylebox", 0)
                        .returns_of(Variant::Nil, "StyleBox"),
                ),
        );
    }

    // -- Missing 2D nodes and resources (pat-0q2kx.106) ---------------------
    //
    // Seventeen Godot 4.6 2D classes had no ClassDB entry at all. That is not
    // cosmetic: `Node::is_class` resolves through ClassDB (gdscene/src/node.rs),
    // so an unregistered node answers `false` to `is_class("CanvasItem")` and
    // silently drops out of every canvas walk — `collect_canvas_items` skips it,
    // and the Create-Node dialog never offers it.
    //
    // Parents are the `inherits` attribute from each class's
    // doc/classes/<Name>.xml; property defaults are that file's `default=`.

    // `CanvasLayer` is registered here rather than assumed: it is
    // ParallaxBackground's parent and appears nowhere else in this file, so
    // without it that chain would resolve to nothing.
    if !class_exists("CanvasLayer") {
        register_class(
            ClassRegistration::new("CanvasLayer")
                .signal(SignalInfo::new("visibility_changed"))
                .parent("Node")
                .property(
                    PropertyInfo::new("layer", Variant::Int(1))
                        .with_accessors("get_layer", "set_layer"),
                )
                .property(
                    PropertyInfo::new("visible", Variant::Bool(true))
                        .with_accessors("is_visible", "set_visible"),
                )
                .property(
                    PropertyInfo::new("offset", Variant::Vector2(Vector2::ZERO))
                        .with_accessors("get_offset", "set_offset"),
                )
                .property(
                    PropertyInfo::new("rotation", Variant::Float(0.0))
                        .with_accessors("get_rotation", "set_rotation"),
                )
                .property(
                    PropertyInfo::new("scale", Variant::Vector2(Vector2::ONE))
                        .with_accessors("get_scale", "set_scale"),
                )
                .property(
                    PropertyInfo::new("follow_viewport_enabled", Variant::Bool(false))
                        .with_accessors("is_following_viewport", "set_follow_viewport"),
                )
                // The last three of the nine `doc/classes/CanvasLayer.xml`
                // members, which were missing (pat-0q2kx.212). `transform` is
                // the one that matters most: Godot lets a layer be positioned
                // either by offset/rotation/scale OR by an explicit transform,
                // and with no property registered the second spelling could not
                // even be authored.
                //
                // ⚠️ Fully qualified: only `Vector2` is imported into this
                // function, so a bare `Transform2D` here is E0433.
                .property(
                    PropertyInfo::new(
                        "transform",
                        Variant::Transform2D(gdcore::math::Transform2D::IDENTITY),
                    )
                    .with_accessors("get_transform", "set_transform"),
                )
                .property(
                    PropertyInfo::new("follow_viewport_scale", Variant::Float(1.0))
                        .with_accessors("get_follow_viewport_scale", "set_follow_viewport_scale"),
                )
                // A NodePath to another Viewport; Nil until assigned.
                .property(
                    PropertyInfo::new("custom_viewport", Variant::Nil)
                        .with_accessors("get_custom_viewport", "set_custom_viewport"),
                ),
        );
    }

