    // -- The rest of Godot's Control tree (pat-s3rrv.71) ---------------------
    //
    // Diffing every `ClassRegistration::new("...")` here against the 4.6.1
    // extension_api Control descendants left these unregistered. Several were
    // ALREADY special-cased by name in the runtime — `control.rs` lays out
    // HFlowContainer and `control_render.rs` draws NinePatchRect — so the
    // engine could draw a class the editor could not create and `is_class`
    // could not resolve. Registration is what the Create Node dialog
    // enumerates and what `Node::is_class` walks.
    //
    // ⚠️ Parents are registered BEFORE their children throughout: a child whose
    // parent is unregistered has a silently severed inheritance chain
    // (pat-nzgdu.98), so `is_class("Control")` would answer false on a class
    // that plainly is one.

    // Abstract bases first. Godot marks Slider, ScrollBar, Separator and the
    // FlowContainer base abstract — they exist to hold the shared surface, and
    // a script must not be able to `.new()` one.
    // `Range` is already registered above with these exact defaults, so the
    // Range family below simply parents to it (pat-s3rrv.71).
    // pat-s3rrv.71: `Slider`, `SpinBox` and `TextureProgressBar` used to be
    // registered a SECOND time here. Both copies sat behind
    // `if !class_exists(..)` in this same function, so the earlier, richer
    // registration always won and these never executed — an edit landing in one
    // of them would have compiled, read correctly and done nothing.
    for slider in ["HSlider", "VSlider"] {
        if !class_exists(slider) {
            register_class(ClassRegistration::new(slider).parent("Slider"));
        }
    }
    if !class_exists("ScrollBar") {
        register_class(
            ClassRegistration::new("ScrollBar")
                .signal(SignalInfo::new("scrolling"))
                .parent("Range")
                .abstract_class()
                .property(
                    PropertyInfo::new("custom_step", Variant::Float(-1.0))
                        .with_accessors("get_custom_step", "set_custom_step"),
                )
                .property(PropertyInfo::new("focus_mode", Variant::Int(3)))
                .property(PropertyInfo::new("step", Variant::Float(0.0))),
        );
    }
    for bar in ["HScrollBar", "VScrollBar"] {
        if !class_exists(bar) {
            register_class(ClassRegistration::new(bar).parent("ScrollBar"));
        }
    }

    // Containers.
    if !class_exists("AspectRatioContainer") {
        register_class(
            ClassRegistration::new("AspectRatioContainer")
                .parent("Container")
                .property(
                    PropertyInfo::new("ratio", Variant::Float(1.0))
                        .with_accessors("get_ratio", "set_ratio"),
                )
                .property(
                    PropertyInfo::new("stretch_mode", Variant::Int(2))
                        .with_accessors("get_stretch_mode", "set_stretch_mode"),
                )
                // ALIGNMENT_CENTER, not BEGIN — the enum's zero is BEGIN and
                // Godot's default is CENTER, so seeding 0 would silently
                // left-align every aspect-ratio container.
                .property(
                    PropertyInfo::new("alignment_horizontal", Variant::Int(1))
                        .with_accessors("get_alignment_horizontal", "set_alignment_horizontal"),
                )
                .property(
                    PropertyInfo::new("alignment_vertical", Variant::Int(1))
                        .with_accessors("get_alignment_vertical", "set_alignment_vertical"),
                )
                .enumeration(
                    EnumInfo::new("StretchMode")
                        .constant("STRETCH_WIDTH_CONTROLS_HEIGHT", 0)
                        .constant("STRETCH_HEIGHT_CONTROLS_WIDTH", 1)
                        .constant("STRETCH_FIT", 2)
                        .constant("STRETCH_COVER", 3),
                )
                .enumeration(
                    EnumInfo::new("AlignmentMode")
                        .constant("ALIGNMENT_BEGIN", 0)
                        .constant("ALIGNMENT_CENTER", 1)
                        .constant("ALIGNMENT_END", 2),
                ),
        );
    }
